import { prisma } from "@/lib/prisma";
import { MatchList } from "./MatchList";

export default async function PredictionsPage() {
  const raw = await prisma.match.findMany({
    where: { competition: "UCL", status: "scheduled" },
    include: {
      homeTeam: true,
      awayTeam: true,
      modelPredictions: {
        orderBy: { createdAt: "desc" },
        take: 1,
      },
    },
    orderBy: { matchDate: "asc" },
  });

  const matches = raw.map((m) => {
    const pred = m.modelPredictions[0] ?? null;
    return {
      id: m.id,
      matchDate: m.matchDate,
      stage: m.stage,
      homeTeam: { name: m.homeTeam.name, country: m.homeTeam.country, logoUrl: m.homeTeam.logoUrl, primaryColor: m.homeTeam.primaryColor, secondaryColor: m.homeTeam.secondaryColor },
      awayTeam: { name: m.awayTeam.name, country: m.awayTeam.country, logoUrl: m.awayTeam.logoUrl, primaryColor: m.awayTeam.primaryColor, secondaryColor: m.awayTeam.secondaryColor },
      prediction: pred
        ? {
            homeWinProb: pred.homeWinProb,
            drawProb: pred.drawProb,
            awayWinProb: pred.awayWinProb,
            homeElo: pred.homeElo,
            awayElo: pred.awayElo,
            eloDiff: pred.eloDiff,
          }
        : null,
    };
  });

  return (
    <main className="max-w-3xl mx-auto p-8">
      <div className="mb-8">
        <h1 className="text-3xl font-bold">Upcoming Matches</h1>
        <p className="text-sm text-gray-500 mt-1">Click a match to see the full prediction breakdown</p>
      </div>

      {matches.length === 0 ? (
        <p className="text-gray-500">No upcoming matches with predictions yet.</p>
      ) : (
        <MatchList matches={matches} />
      )}
    </main>
  );
}
